(function(){
 'use strict';
 const G=window.HZLGeopolitics;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let selected='Zinc',lastEvent=null;
 const launcher=document.createElement('button');launcher.id='assistant-launch';launcher.textContent='Ask market assistant';launcher.setAttribute('aria-haspopup','dialog');launcher.setAttribute('aria-expanded','false');
 const panel=document.createElement('dialog');panel.id='market-assistant';panel.setAttribute('aria-labelledby','assistant-title');
 panel.innerHTML=`<div class="assistant-head"><div><h2 id="assistant-title">Market scenario assistant</h2><small>Guided answers · no LLM or live news feed</small></div><button id="assistant-close" aria-label="Close market assistant">×</button></div><p class="mini">Dated evidence + explicit assumptions. Chats stay in this browser session. Refresh clears them.</p><label for="assistant-metal">Metal for this conversation</label><select id="assistant-metal"><option>Zinc</option><option>Lead</option><option>Silver</option></select><div class="assistant-prompts">${G.events.map(e=>`<button class="secondary" data-ask="${e.id}">${esc(e.id==='russia-ukraine'?'Russia–Ukraine':e.id==='iran-conflict'?'Iran / Gulf conflict':'Red Sea shipping')}</button>`).join('')}<button class="secondary" data-ask="forecast">How does the forecast change?</button></div><div id="assistant-messages" role="log" aria-live="polite" aria-label="Conversation"></div><form id="assistant-form"><label for="assistant-question">Ask about events, demand, pricing or allocation</label><div class="assistant-compose"><input id="assistant-question" maxlength="600" autocomplete="off" required placeholder="How could Iran conflict affect zinc?"><button type="submit">Send</button></div></form><button id="assistant-clear" class="secondary">Clear conversation</button>`;
 document.body.append(launcher,panel);
 const log=panel.querySelector('#assistant-messages');
 function add(who,text,html=false){const item=document.createElement('div');item.className='assistant-message '+who;const label=document.createElement('strong');label.textContent=who==='user'?'You':'Assistant';item.append(label);const body=document.createElement('div');if(html)body.innerHTML=text;else body.textContent=text;item.append(body);log.append(item);while(log.children.length>30)log.firstElementChild.remove();item.scrollIntoView({block:'nearest'});}
 function eventReply(e){lastEvent=e;const p=G.preset(e,selected),unit=selected==='Silver'?'kg':'t';add('assistant',`<h3>${esc(e.title)}</h3><p><strong>Reported evidence:</strong> ${esc(e.fact)}</p><p>${esc(e.period)} · published ${e.published}. <a href="${e.url}" target="_blank" rel="noopener noreferrer">${esc(e.source)}</a></p><p><strong>${selected} transmission:</strong> ${esc(e.notes[selected])}</p><p><strong>Illustrative stress test, not a measured effect:</strong> orders ${p.demandShock}%; reference price +${p.priceShock}%; premium +${p.premiumShift} USD/${unit}; freight +${p.freightShift} USD/${unit}; ETA +${p.delay} days. Demand weights: 1, 0.75, 0.5. These are assumptions, not probabilities.</p><p>${esc(e.limit)} Price rises do not establish demand growth. Booked commitments stay protected.</p><button data-draft="${e.id}" data-metal="${selected}">Open editable ${selected} scenario draft</button><p class="mini">Opening a draft does not change the dashboard. Verify exposure, calculate, review, then apply. Silver effects remain in the Silver event workspace.</p>`,true);}
 function answer(q){add('user',q);const text=q.toLowerCase();const e=G.events.find(e=>text.includes(e.id)|| (e.id==='russia-ukraine'&&/russia|ukraine/.test(text))||(e.id==='iran-conflict'&&/iran|hormuz|gulf/.test(text))||(e.id==='red-sea'&&/red sea|suez/.test(text)));if(e)return eventReply(e);
 if(/latest|today|current news|predict.*war/.test(text))return add('assistant','I cannot provide live news or predict whether a war will occur. Choose a dated event above to examine its evidence, then test explicit assumptions. No live market or news service is connected.');
 if(/forecast|demand|impact|why|change/.test(text))return add('assistant','The customer baseline uses requirements × planned HZL share, with booked commitments protected. An event draft changes expected orders by sensitivity × verified exposure × monthly weight. Freight, reference price, premium and FX change separately. Calculate and review shows monthly baseline versus scenario, domestic reserve, residual export and delayed arrivals. These are conditional calculations, not trained geopolitical predictions. '+(lastEvent?'Open the draft in the event answer above to see numeric impacts.':'Choose an event above to start.'));
 if(/price|premium|freight|duty|forex|fx/.test(text))return add('assistant','Import parity combines metal reference + premium + incremental freight, converts USD to INR, then adds duty and depot costs. Avoid double-counting freight already included in a premium. Scenarios are sensitivity tests; auction premiums still require comparable offers and commercial review.');
 if(/allocat|export|domestic/.test(text))return add('assistant','Domestic reservation follows expected orders / booked commitments plus buffer, capped at capacity. Remaining capacity is a potential export allocation; grade, market access, credit and netback still require review.');
 add('assistant','I can explain Russia–Ukraine, Iran / Gulf conflict, Red Sea shipping, forecast changes, pricing and allocation. Use a suggested question above. This guided assistant does not answer arbitrary questions or use a language model.');}
 launcher.onclick=()=>{panel.showModal();launcher.setAttribute('aria-expanded','true');panel.querySelector('#assistant-question').focus();};panel.querySelector('#assistant-close').onclick=()=>panel.close();panel.addEventListener('close',()=>{launcher.setAttribute('aria-expanded','false');launcher.focus();});
 panel.querySelector('#assistant-metal').onchange=e=>{selected=e.target.value;lastEvent=null;add('assistant','Conversation metal changed to '+selected+'. Choose an event for metal-specific assumptions. Previous answers keep their original metal.');};
 panel.querySelector('#assistant-form').onsubmit=e=>{e.preventDefault();const input=panel.querySelector('#assistant-question'),q=input.value.trim();if(!q)return;input.value='';answer(q);};
 panel.addEventListener('click',e=>{const ask=e.target.closest('[data-ask]');if(ask){answer(ask.dataset.ask==='forecast'?'How does the forecast change?':ask.dataset.ask);return;}const draft=e.target.closest('[data-draft]');if(draft){const event=G.events.find(x=>x.id===draft.dataset.draft),metal=draft.dataset.metal||selected;window.HZLPlanning.queueFromCase(metal,event,G.preset(event,metal));panel.close();}});
 panel.querySelector('#assistant-clear').onclick=()=>{log.replaceChildren();lastEvent=null;add('assistant','Conversation cleared. Select a dated event to explore a conditional scenario.');};
 add('assistant','Select Zinc, Lead or Silver, then choose a geopolitical event. I will separate published evidence from scenario assumptions and help you open an editable forecast draft.');
})();
